export const TURN_RESUME_PROMPT = '继续上次未完成的工作。结合任务清单、已完成步骤和我补充过的说明，接着做到完成。'
const TURN_INTERRUPT_NOTICE='终止打断了'
const TURN_ERROR_NOTICE='无法执行。'
const TURN_ERROR_TIMEOUT_CAUSE='请求超时，请稍后重试。'
const TURN_ERROR_TOO_LARGE_CAUSE='回复或工具参数过大，请减少内容后重试。'
const TURN_ERROR_INCOMPLETE_CAUSE='模型结果不完整，请重试。'
export const isChatStreamFailure=(code:string)=>/^(UPSTREAM_|PROVIDER_|REQUEST_TOO_LARGE|ASSISTANT_RESPONSE_TOO_LARGE|MESSAGE_STORAGE|HOST_BUSY|ENGINE_BUSY)/.test(code)
export function turnFailureNotice(err?: {code?: string} | null): string {
  const code=err?.code??''
  if(code==='UPSTREAM_TIMEOUT'||code.includes('TIMEOUT'))return TURN_ERROR_NOTICE+TURN_ERROR_TIMEOUT_CAUSE
  if(code==='ASSISTANT_RESPONSE_TOO_LARGE'||code==='REQUEST_TOO_LARGE')return TURN_ERROR_NOTICE+TURN_ERROR_TOO_LARGE_CAUSE
  return TURN_ERROR_NOTICE+TURN_ERROR_INCOMPLETE_CAUSE
}
const appendTurnNotice=(prev:string,notice:string)=>{if(prev.includes(notice))return prev;if(notice.startsWith(TURN_ERROR_NOTICE)&&prev.includes(TURN_ERROR_NOTICE))return prev;const t=prev.trim();return t?`${t}\n${notice}`:notice}
const turnStorageKey = (id: string) => `lunitide:active-turn:${id}`
type ActiveTurn = { status: 'running' | 'interrupted' | 'cancelled'; resumeCount: number }
const readActiveTurn = (id: string): ActiveTurn | undefined => {
  try {
    const v = JSON.parse(localStorage.getItem(turnStorageKey(id)) || '')
    if (v && typeof v === 'object' && (v.status === 'running' || v.status === 'interrupted' || v.status === 'cancelled')) return v
  } catch { /* ignore */ }
}
const writeActiveTurn = (id: string, patch: Partial<ActiveTurn>) => {
  if (!id) return
  const prev = readActiveTurn(id) ?? { status: 'running' as const, resumeCount: 0 }
  try { localStorage.setItem(turnStorageKey(id), JSON.stringify({ ...prev, ...patch })) } catch { /* quota / private mode */ }
}
const clearActiveTurn = (id: string) => localStorage.removeItem(turnStorageKey(id))
